public class IconDetector extends Detector implements BinaryResourceScanner {
    private static final String PNG = "png";
    private static final String WEBP = "webp";
    private static final String GIF = "gif";

    public static final Issue ISSUE = Issue.create(
        "IconExtension",
        "Icon format does not match the file extension",
        "Ensures that icons have the correct file extension (e.g. a `.png` file is really in the PNG format and not for example a GIF file named `.png`).",
        Category.ICONS,
        5,
        Severity.WARNING,
        new Implementation(IconDetector.class, Scope.BINARY_RESOURCE_FILE_SCOPE)
    );

    @Override
    public void checkBinaryResource(@NonNull BinaryResourceContext context) {
        String fileName = context.file.getName();
        String extension = getExtension(fileName);
        if (extension == null) return;
        byte[] data = context.getData();
        if (data == null || data.length < 8) return;
        String actualFormat = detectFormat(data);
        if (actualFormat == null) return;
        if (!actualFormat.equalsIgnoreCase(extension)) {
            String message = String.format(
                "The file name extension is `.%1$s`, but the actual icon format is `%2$s`. Rename the file to `.%2$s` or convert it to the `%1$s` format.",
                extension, actualFormat
            );
            context.report(ISSUE, Location.create(context.file), message);
        }
    }

    private static String getExtension(String fileName) {
        int dot = fileName.lastIndexOf('.');
        if (dot == -1 || dot == fileName.length() - 1) return null;
        return fileName.substring(dot + 1);
    }

    private static String detectFormat(byte[] data) {
        if (data.length >= 8
            && data[0] == (byte) 0x89
            && data[1] == 0x50
            && data[2] == 0x4E
            && data[3] == 0x47
            && data[4] == 0x0D
            && data[5] == 0x0A
            && data[6] == 0x1A
            && data[7] == 0x0A) {
            return PNG;
        }
        if (data.length >= 6
            && data[0] == 'G'
            && data[1] == 'I'
            && data[2] == 'F'
            && data[3] == '8'
            && (data[4] == '7' || data[4] == '9')
            && data[5] == 'a') {
            return GIF;
        }
        if (data.length >= 12
            && data[0] == 'R'
            && data[1] == 'I'
            && data[2] == 'F'
            && data[3] == 'F'
            && data[8] == 'W'
            && data[9] == 'E'
            && data[10] == 'B'
            && data[11] == 'P') {
            return WEBP;
        }
        return null;
    }
}

