@Override
public void checkBinaryResource(@NotNull ResourceContext context) {
    Location location = context.getLocation();
    if (location == null) {
        return;
    }
    File file = location.getFile();
    if (file == null) {
        return;
    }
    if (file.isDirectory()) {
        try (Stream<Path> paths = Files.walk(file.toPath())) {
            paths.filter(Files::isRegularFile)
                 .forEach(path -> checkFile(context, path.toFile()));
        } catch (IOException e) {
            // ignore
        }
    } else {
        checkFile(context, file);
    }
}

private void checkFile(ResourceContext context, File file) {
    String fileName = file.getName();
    String extension = getExtension(fileName);
    if (extension == null) return;
    byte[] data;
    try {
        data = Files.readAllBytes(file.toPath());
    } catch (IOException e) {
        return;
    }
    if (data.length < 6) return;
    String actualFormat = detectFormat(data);
    if (actualFormat == null) return;
    if (!actualFormat.equalsIgnoreCase(extension)) {
        String message = String.format(..., extension, actualFormat);
        context.report(ISSUE, Location.create(file), message);
    }
}
```

